properties.query:
// Find all HalcyonEvents_CL records related to a specific HalcyonAlertId.
// Replace <HalcyonAlertIdFromIncident> with the HalcyonAlertId custom detail from the Sentinel incident.
let TargetAlertId = "<HalcyonAlertIdFromIncident>";
HalcyonEvents_CL
| extend HalcyonInstancesAlertId = tostring(finding_info.uid)
| where HalcyonInstancesAlertId == TargetAlertId
| order by TimeGenerated desc
